import type { SupabaseClient } from "@supabase/supabase-js";
import type { Database } from "../db/types.ts";
import type { Paypal } from "./paypal.ts";

// Tutoring money steps (F17, 06 §12, §15, 10 MVP-07), shared by the Next server (the learner
// confirms, admin resolves a dispute, the webhook) and the worker (auto-release 24 h after the
// session). The authorisation is captured, then the tutor is paid out minus the take rate. Every
// state change goes through `booking_step`, idempotent on the booking; PayPal calls carry request
// ids, so a retried step never moves money twice.

export type Booking = Database["public"]["Tables"]["tutoring_bookings"]["Row"];
type Db = SupabaseClient<Database>;

/** The tutor's share: the price less Ifiok's commission (take rate in basis points). */
export function tutorShareCents(priceCents: number, takeRateBp: number): number {
  return priceCents - Math.round((priceCents * takeRateBp) / 10_000);
}

/** When a held booking releases on its own if the learner hasn't confirmed or disputed it. */
export function autoReleaseAt(b: Pick<Booking, "starts_at" | "minutes">, hours: number): Date {
  return new Date(new Date(b.starts_at).getTime() + (b.minutes * 60 + hours * 3600) * 1000);
}

async function step(db: Db, id: string, to: string, ref: string | null = null, note: string | null = null) {
  const { data, error } = await db.rpc("booking_step", {
    p_booking: id,
    p_to: to,
    p_ref: ref as unknown as string,
    p_note: note as unknown as string,
  });
  if (error) throw new Error(`booking_step ${to} failed`);
  return data === true;
}

async function load(db: Db, id: string): Promise<Booking | null> {
  const { data } = await db.from("tutoring_bookings").select("*").eq("id", id).maybeSingle();
  return data;
}

export type ReleaseOutcome = "paid_out" | "waiting_for_tutor_email" | "not_held";

/**
 * Captures a held booking and pays the tutor. `by` is who released it. Safe to repeat: a captured
 * booking only gets its payout, a paid-out one nothing.
 */
export async function releaseBooking(
  deps: { db: Db; paypal: Paypal },
  id: string,
  by: "learner" | "auto" | "admin",
): Promise<ReleaseOutcome> {
  let b = await load(deps.db, id);
  if (!b) return "not_held";
  if (b.status === "authorized" || (b.status === "disputed" && by === "admin")) {
    if (!b.paypal_authorization_id) throw new Error("booking has no authorisation");
    const capture = await deps.paypal.captureAuthorization(b.paypal_authorization_id);
    if (!["COMPLETED", "PENDING"].includes(capture.status)) throw new Error(`capture ${capture.status}`);
    await step(deps.db, id, "captured", capture.id, by);
    b = await load(deps.db, id);
  }
  if (!b || b.status === "paid_out") return b ? "paid_out" : "not_held";
  if (b.status !== "captured") return "not_held";
  return payTutor(deps, b);
}

/** Pays a captured booking's tutor, once (the sender batch id is the booking). */
export async function payTutor(deps: { db: Db; paypal: Paypal }, b: Booking): Promise<ReleaseOutcome> {
  const { data: account } = await deps.db
    .from("payout_accounts")
    .select("paypal_email")
    .eq("user_id", b.tutor_id)
    .maybeSingle();
  if (!account) return "waiting_for_tutor_email";
  await deps.paypal.createPayout(`booking-${b.id}`, "Your Ifiok tutoring session (sandbox)", [
    {
      receiver: account.paypal_email,
      amountCents: tutorShareCents(b.price_cents, b.take_rate_bp),
      senderItemId: `booking:${b.id}`,
      note: "Ifiok tutoring session, after Ifiok's commission. Sandbox: test money.",
    },
  ]);
  await step(deps.db, b.id, "paid_out");
  return "paid_out";
}

/** Tutor no-show (F17-FR5): the hold is voided, so the learner is never charged. */
export async function voidBooking(deps: { db: Db; paypal: Paypal }, id: string, reason: string): Promise<boolean> {
  const b = await load(deps.db, id);
  if (!b || !["authorized", "disputed"].includes(b.status) || !b.paypal_authorization_id) return false;
  await deps.paypal.voidAuthorization(b.paypal_authorization_id);
  return step(deps.db, id, "voided", null, reason);
}

export { step as bookingStep, load as loadBooking };
